+                    }
+                }
+                unsafeExtendWith(buffer);
+            }
+            if (restoreTemp.length == 0) {
+                order = buffer.order();
+                readOnly = buffer.readOnly();
+            }
+        } catch (Exception e) {
+            bufs = restoreTemp;
+            throw e;
+        }
+    }
