+     */
+    protected void unsafeSetDrop(Drop<T> replacement) {
+        drop = Objects.requireNonNull(replacement, "Replacement drop cannot be null.");
+    }
+
+    @SuppressWarnings("unchecked")
+    private I self() {
+        return (I) this;
+    }
+
+    @SuppressWarnings("unchecked")
+    private T impl() {
+        return (T) this;
+    }
+}

