+        }
+        return numFreed;
+    }
+
+    private static int free(MemoryRegionCache cache) {
+        if (cache == null) {
+            return 0;
+        }
+        return cache.free();
+    }
+
+    void trim() {
+        trim(smallSubPageCaches);
+        trim(normalCaches);
+    }
+
+    private static void trim(MemoryRegionCache[] caches) {
