+
+class PooledAllocatorControl implements AllocatorControl {
+    public PooledBufferAllocator parent;
+    public PoolArena arena;
+    public PoolChunk chunk;
+    public PoolThreadCache threadCache;
+    public long handle;
+    public int normSize;
