+        return new ByteCursor() {
+            final UnsafeMemory memory = UnsafeBuffer.this.memory; // Keep memory alive.
+            final Object baseObj = base;
+            final long baseAddress = address;
+            int index = fromOffset;
+            final int end = index + length;
+            long longValue = -1;
+            byte byteValue = -1;
