+                    try {
+                        byteValue = PlatformDependent.getByte(baseObj, baseAddress + index);
+                    } finally {
+                        Reference.reachabilityFence(memory);
+                    }
+                    index--;
+                    return true;
+                }
+                return false;
+            }
