+        LongPriorityQueue pq = new LongPriorityQueue();
+        for (int i = 0; i < initialValues; i++) {
+            long value = tlr.nextLong(0, Long.MAX_VALUE);
+            pq.offer(value);
+            values.add(value);
+        }
+        for (Long value : values) {
+            pq.remove(value);
+        }
